param([string]$RepoRoot='C:\Users\aaron\Desktop\URAP',[string]$RunId='nps_action_bank_listwise_v3')
$root=Join-Path $RepoRoot 'artifacts\detached_nps_action_bank_listwise_v3';$pidFile=Join-Path $root ($RunId+'.pid');$metaFile=Join-Path $root ($RunId+'.meta.json')
$pidValue=if(Test-Path $pidFile){[int](Get-Content $pidFile|Select-Object -First 1)}else{0};$process=if($pidValue){Get-Process -Id $pidValue -ErrorAction SilentlyContinue}else{$null};$meta=if(Test-Path $metaFile){Get-Content $metaFile -Raw|ConvertFrom-Json}else{$null}
$progress=if($meta -and (Test-Path $meta.progress)){Get-Content $meta.progress -Raw|ConvertFrom-Json}else{$null};$child=if($progress -and $progress.child_pid){Get-CimInstance Win32_Process -Filter "ProcessId=$($progress.child_pid)" -ErrorAction SilentlyContinue}else{$null};$runtime=if($progress -and $progress.child_pid){Get-CimInstance Win32_Process -Filter "ParentProcessId=$($progress.child_pid)" -ErrorAction SilentlyContinue|Select-Object -First 1}else{$null}
$last=if($meta -and (Test-Path $meta.stdout)){Get-Content $meta.stdout -Tail 1}else{'none'};$gpu=if($meta -and (Test-Path $meta.stdout)){Get-Content $meta.stdout -Tail 100|Select-String 'cuda_memory_allocated_mb'|Select-Object -Last 1}else{$null}
Write-Output "status: $(if($process){'RUNNING'}else{'NOT RUNNING'})";Write-Output "done/total: $(if($progress){$progress.done.ToString()+'/'+$progress.total}else{'0/4'})";Write-Output "stage: $(if($progress){$progress.stage}else{'not_started'})";Write-Output "pid: $pidValue";Write-Output "start_time: $(if($process){$process.StartTime}else{if($meta){$meta.started}else{'unknown'}})";Write-Output "child_pid: $(if($progress){$progress.child_pid}else{'none'})";Write-Output "child_command: $(if($child){$child.CommandLine}else{'none'})";Write-Output "runtime_pid: $(if($runtime){$runtime.ProcessId}else{'none'})";Write-Output "last_output_timestamp: $(if($meta -and (Test-Path $meta.stdout)){(Get-Item $meta.stdout).LastWriteTime}else{'none'})";Write-Output "last_completed_unit: $last";Write-Output "gpu_signal: $(if($gpu){$gpu.Line}else{'NO GPU SIGNAL YET'})";Write-Output "stdout: $($meta.stdout)";Write-Output "stderr: $($meta.stderr)";Write-Output "progress: $($meta.progress)"
